srcDoc.css:
body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: #f6f8fc;
  color: #111827;
}

.action-center {
  padding: 18px;
}

.action-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: flex-start;
  margin-bottom: 14px;
}

.action-head h2 {
  margin: 0;
  font-size: 22px;
  font-weight: 850;
}

.action-head p {
  margin: 4px 0 0;
  color: #64748b;
  font-size: 13px;
}

.count-pill {
  background: #111827;
  color: #fff;
  border-radius: 999px;
  padding: 7px 11px;
  font-size: 12px;
  font-weight: 850;
}

.action-list {
  display: grid;
  gap: 10px;
}

.action-card {
  border: 1px solid #e5e9f2;
  background: #fff;
  border-radius: 10px;
  padding: 13px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.06);
}

.action-card strong {
  display: block;
  font-size: 14px;
}

.action-card span {
  display: block;
  margin-top: 4px;
  color: #64748b;
  font-size: 12px;
}

.action-card small {
  display: inline-flex;
  margin-top: 8px;
  color: #475569;
  font-weight: 800;
  font-size: 11px;
}

.severity {
  align-self: start;
  border-radius: 999px;
  padding: 5px 9px;
  font-size: 11px;
  font-weight: 900;
}

.high {
  border-color: #fecaca;
  background: #fff7f7;
}

.high .severity {
  background: #fee2e2;
  color: #b91c1c;
}

.medium {
  border-color: #fde68a;
  background: #fffbeb;
}

.medium .severity {
  background: #fef3c7;
  color: #92400e;
}

.low .severity {
  background: #e8eef8;
  color: #475569;
}

.empty {
  height: 180px;
  display: grid;
  place-items: center;
  color: #94a3b8;
  border: 1px dashed #dbe3ef;
  border-radius: 10px;
}

