const root = document.getElementById("action-center-root");
function esc(value) {
  return String(value ?? "").replace(/[&<>"']/g, char => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#039;"
  })[char]);
}
function render() {
  const model = appsmith.model || {};
  const items = model.items || [];
  root.innerHTML = `
    <div class="action-center">
      <div class="action-head">
        <div>
          <h2>Action Center</h2>
          <p>Updated ${esc(model.generatedAt || "")}</p>
        </div>
        <div class="count-pill">${Number(model.totalCount || 0)} open</div>
      </div>

      ${items.length ? `<div class="action-list">
              ${items.map((row, index) => `
                <div class="action-card ${String(row.severity || "LOW").toLowerCase()}" data-index="${index}">
                  <div>
                    <strong>${esc(row.title || "")}</strong>
                    <span>${esc(row.detailText || "")}</span>
                    <small>${esc(row.moduleName || "")} · ${Number(row.countValue || 0)} item(s)</small>
                  </div>
                  <div class="severity">${esc(row.severity || "LOW")}</div>
                </div>
              `).join("")}
            </div>` : `<div class="empty">No urgent actions right now.</div>`}
    </div>
  `;
  document.querySelectorAll(".action-card").forEach(card => {
    card.onclick = () => {
      const index = Number(card.dataset.index || 0);
      appsmith.updateModel({
        selectedAction: items[index]
      });
      appsmith.triggerEvent("actionSelected");
    };
  });
}
appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});

